actions.script:
const smithy = ec.resource.script("component://mr-mantle/service/mantle/smithy/Smithy.js")
if (input != null) {
    result = smithy.execute("createRepository", input)
    return
}
if (!siteId) { ec.message.addError("siteId is required"); return }
const made = smithy.createRepository({siteId, groupId, slug, name, description, visibility, repositoryKind, branch})
repositoryId = made.repositoryId
repositoryPath = made.repositoryPath
